const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const minLat = -68; // 68° South
  const maxLat = -56; // 56° South
  // Define a rectangle covering the entire longitude range for the specified latitude band.
  const geometry = ee.Geometry.Rectangle([-180, minLat, 180, maxLat]);
  const date = '2016-01-13';
  const endDate = '2016-01-14'; // End date is exclusive, so it covers Jan 13 fully.
  const bloomThreshold = 1.0; // Chlorophyll-a concentration in mg/m^3 to signify a bloom.

  // 2. Data Acquisition & Check
  // Using MODIS Aqua Chlorophyll A concentration (8-day composite for better coverage)
  // Although daily data exists, 8-day is often more reliable for ocean color.
  // For a single day, we will filter for that day.
  let collection = ee.ImageCollection('MODIS/006/AQUA_CHL')
    .filterDate(date, endDate)
    .filterBounds(geometry);

  const colSize = await collection.size().getInfo();
  if (colSize === 0) {
    console.log(`No MODIS Aqua Chlorophyll-a data found for ${date}.`);
    console.log('C1');
    return;
  }
  console.log(`Images found for ${date}: ${colSize}`);

  // Get the first image, or mosaic if multiple exist for the day (e.g., from different orbits).
  const image = collection.mosaic().select('chlor_a');

  // 3. Processing & Calculation
  // Define a reasonable scale for ocean data (e.g., 4000m for MODIS data to avoid excessive computation)
  const scale = 4000;

  // Calculate the mean chlorophyll-a concentration and the count of valid pixels within the geometry.
  const reduction = await image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 4
  }).getInfo();

  const meanChlorA = reduction['chlor_a_mean'];
  const validPixels = reduction['chlor_a_count'];

  // 4. Validation & Final Answer
  if (validPixels === null || validPixels === 0) {
    console.log('No valid pixels after masking in the specified region for January 13, 2016.');
    console.log('C2');
    return;
  }

  if (meanChlorA === null || isNaN(meanChlorA)) {
    console.log('Calculation for mean chlorophyll-a failed.');
    console.log('C3');
    return;
  }

  console.log(`Mean Chlorophyll-a: ${meanChlorA.toFixed(2)} mg/m^3`);
  console.log(`Valid Pixels (scale ${scale}m): ${validPixels}`);
  console.log(`Bloom Threshold: ${bloomThreshold} mg/m^3`);

  if (meanChlorA > bloomThreshold) {
    console.log('A'); // Yes, a phytoplankton bloom was visible
  } else {
    console.log('B'); // No, a phytoplankton bloom was not visible
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
